enum HostingAccountStatus {
  PENDING // created, waiting for the provisioner
  PROVISIONING
  ACTIVE
  SUSPENDED
  FAILED
  DELETING
}

/// One customer's isolated shared-hosting account on a HostingNode: a jailed
/// Linux user with its own PHP-FPM pool, disk quota, primary domain and (later)
/// additional sites / databases / mailboxes. The unit of isolation and billing.
model HostingAccount {
  id                String                 @id @default(cuid())
  userId            String
  user              User                   @relation(fields: [userId], references: [id], onDelete: Cascade)
  // Set when this order arrived via a partner deep link (?ref=kodely on
  // /dashboard/deploy?product=hosting, captured by PartnerSourceCapture). Null for
  // every direct Nxeon order. Gates the webhook notify in worker/hosting.ts.
  partnerSource     String?
  hostingNodeId     String
  node              HostingNode            @relation(fields: [hostingNodeId], references: [id])
  planId            String
  plan              HostingPlan            @relation(fields: [planId], references: [id])
  // The jailed system username on the box (derived, unique per node). All the
  // account's files live under /home/<username>; its FPM pool runs AS this user.
  username          String
  primaryDomain     String // the account's main domain (name-based vhost server_name)
  status            HostingAccountStatus   @default(PENDING)
  // Effective quota snapshot (copied from the plan at creation so a plan edit
  // doesn't silently re-quota live accounts). ALWAYS already includes any purchased
  // `extraDiskGB` — it is (plan.diskGB + extraDiskGB) × 1024 — so the node's setquota
  // (taskApplyPlanLimits) never has to know about the add-on.
  diskQuotaMB       Int
  /// Purchased extra storage in GB, on TOP of the plan allowance (upsell). Add-only,
  /// mirroring Server.extraDiskGB — a live filesystem quota is only ever raised, never
  /// shrunk. Priced per-GB/month via `extra_disk_gb_price_cents` (the SAME rate VPS
  /// extra disk uses) and billed every renewal alongside the plan.
  extraDiskGB       Int                    @default(0)
  maxSites          Int
  maxDatabases      Int
  /// Billing term this account was SOLD on, in months: 1 = monthly, 12 = annual.
  /// The renewal sweep (worker/product-renewals.ts) charges
  /// `termPriceCents(plan.priceCents, termMonths, annualDiscountPct)` and pushes
  /// `expiresAt` forward this many months, so an annual account renews annually at
  /// the rate it was sold — displayed === charged === renewed. Defaults to 1 so
  /// every pre-existing row keeps billing monthly exactly as before.
  termMonths        Int                    @default(1)
  /// PERCENT the ANNUAL discount was set to when THIS account's term was sold — a
  /// snapshot of `annual_discount_percent` frozen at sale, exactly like
  /// Server.annualDiscountPct. The renewal reads THIS (falling back to the live
  /// setting when null) so an annual account renews at the sold rate even if the
  /// admin retunes the discount afterwards. NULL on monthly accounts and on rows
  /// that predate this column — the live setting is used for those, which for a
  /// monthly term changes nothing.
  annualDiscountPct Float?
  // PHP version the account's FPM pool runs (within the plan's allowed set).
  phpVersion        String                 @default("8.3")
  // HTTPS: set once a per-domain Let's Encrypt cert is issued (SNI on the shared
  // IP). The SSL sweep flips this after the domain resolves to us.
  sslActive         Boolean                @default(false)
  // Live disk/inode usage, refreshed by hostingUsageSweep (null until first
  // measured). Powers the real usage meters in the customer panel.
  diskUsedMB        Int?
  inodesUsed        Int?
  usageAt           DateTime?
  /// WHERE that disk is going, as JSON: `{"v":1,"dirs":[{"path":"public_html","mb":123},…]}`
  /// — one `du -sm` per top-level directory in the account home plus each site's
  /// docroot, written by the SAME hostingUsageSweep pass that writes diskUsedMB,
  /// so the parts and the total are always measured together and cannot disagree.
  /// NULL means no sweep has run against a real node yet; the panel says that
  /// rather than drawing an empty breakdown that reads as "nothing stored".
  usageBreakdown    String?
  // Serve-verification health, refreshed by hostingHealthSweep (null until first
  // checked). serveHttpOk/serveHttpsOk record whether nginx actually answers on
  // 80/443 for this domain from the node — the guardrail against a customer ever
  // seeing ERR_CONNECTION_REFUSED while the panel claims "active". healthNote is a
  // short human string for the DNS→HTTPS stepper; healthCheckedAt timestamps it.
  // recheckRequested is set by the customer "Check now / Go live" button so the
  // sweep picks that account up before its normal cadence, then clears it.
  serveHttpOk       Boolean?
  serveHttpsOk      Boolean?
  healthNote        String?
  healthCheckedAt   DateTime?
  recheckRequested  Boolean                @default(false)
  // The account's SFTP/login password, encrypted; set at provision and shown to
  // the customer ONCE, then cleared. (SFTP is a reviewed later phase.)
  sftpPasswordEnc   String?
  // The per-account, hard-to-guess URL path where the Adminer DB manager is
  // dropped inside this account's own webroot (e.g. /nxtools-<random>/adminer.php),
  // served by this account's own PHP-FPM socket. Null until the customer installs
  // it from the Databases tab. A leaked path yields no cross-tenant access: the
  // customer must still log in with their OWN scoped DB user (localhost, granted on
  // their databases only). See INSTALL_DBTOOL in worker/hosting.ts.
  dbToolPath        String?
  // Proprietary in-portal DB manager (Nxeon-built, replaces Adminer). A single
  // account-level MySQL user granted on `<username>\_%`.* ONLY — i.e. every one of
  // this account's databases and NOTHING else (db-scoped grant, so no global
  // FILE/PROCESS/SUPER either). Its password is encrypted AT REST (persistent,
  // like sftpPasswordEnc) because the manager re-authenticates as this user on
  // every query, server-side — the credential is NEVER sent to the browser. The
  // ENSURE_DBMGR task creates the user on the node; dbMgrReady flips true when it
  // succeeds. See lib/hosting-db.ts + lib/actions-hosting-db.ts.
  dbMgrUser         String?
  dbMgrPassEnc      String?
  dbMgrReady        Boolean                @default(false)
  // Provisioning bookkeeping.
  error             String?
  // Best-effort, human-readable label for whichever real provisioning step is
  // running right now (e.g. "Creating your account…", "Configuring your web
  // server…") — written by worker/hosting.ts's provisionHostingAccount() /
  // applyIsolation() between real, observable command groups. Read (alongside a
  // live HostingTask, e.g. a queued WordPress install) by
  // lib/provisioning-step.ts and shown by <ProvisioningOverlay/>. Null = no real
  // signal yet (falls back to a generic message) or not mid-provision.
  provisioningStep  String?
  provisionedAt     DateTime?
  expiresAt         DateTime?
  suspendedNote     String?
  createdAt         DateTime               @default(now())
  updatedAt         DateTime               @updatedAt
  databases         HostingDatabase[]
  tasks             HostingTask[]
  backups           HostingBackup[]
  subdomains        HostingSubdomain[]
  addonDomains      HostingAddonDomain[]
  crons             HostingCron[]
  hostnameClaims    HostingHostnameClaim[]
  ftpUsers          HostingFtpUser[]
  siteThumbs        HostingSiteThumb[]

  @@unique([hostingNodeId, username])
  @@index([userId])
  @@index([status])
}

/// Which kind of resource a hostname claim reserves. Purely descriptive — the
/// authoritative guarantee is the UNIQUE(hostname) on the claim row itself.
enum HostingClaimKind {
  PRIMARY
  SUBDOMAIN
  ADDON
}

/// Single authoritative registry of every hostname served on the fleet, spanning
/// ALL THREE places a name can live — an account's primary domain, a subdomain,
/// or an addon domain. The UNIQUE(hostname) is the atomic cross-tenant guard: a
/// claim row is inserted in the SAME transaction as the resource row it names, so
/// two concurrent requests that both pass the advisory isHostnameClaimed()
/// pre-check can never both commit the same nginx `server_name` — the second
/// INSERT fails on the unique (Prisma P2002) and rolls its whole transaction back.
/// Before this table there was no single constraint spanning the three hostname
/// tables (primaryDomain has no unique), so co-tenants on one node could shadow
/// each other's vhost (security audit: co-tenant vhost-shadowing TOCTOU). The
/// hostname is stored normalized (trimmed + lowercased) so case/format variants
/// can't dodge the unique. Freed by deleting the row when the resource is removed
/// (same tx as the delete / on account termination); the accountId relation also
/// cascades if the account row is ever hard-deleted.
model HostingHostnameClaim {
  id        String           @id @default(cuid())
  hostname  String           @unique
  accountId String
  account   HostingAccount   @relation(fields: [accountId], references: [id], onDelete: Cascade)
  kind      HostingClaimKind

model GamePlan {
  id           String   @id @default(cuid())
  gameFamily   String // minecraft, valheim, rust, palworld, cs2, terraria, ...
  name         String // e.g. "Minecraft — 4 GB / 20 slots"
  ramMB        Int
  cpuCores     Int      @default(2)
  diskGB       Int
  slots        Int? // player slots (nullable)
  priceCents   Int // retail price the customer pays (per term) — the REGULAR/renewal rate
  /// GRANDFATHER PROGRAM (2026-09-17): mirrors Plan.introPriceCents/introTermMonths
  /// exactly — a lower first-term price that renews at the regular `priceCents`
  /// above. Read by the same generic lib/intro-pricing.ts helpers VPS already
  /// uses (planIntroMonthlyCents/planIntroTermMonths take a `{priceCents}`-shaped
  /// row, so a GamePlan works with zero new code there). NULL introTermMonths
  /// means the WHOLE first term (any length) bills at introPriceCents.
  introPriceCents Int?
  introTermMonths Int?
  termMonths   Int      @default(1)
  basePlanId   String // the VPS Plan used to size/provision the VM
  basePlan     Plan     @relation(fields: [basePlanId], references: [id])
  osTemplateId String? // the game's OsTemplate (image) to deploy
  featured     Boolean  @default(false)
  active       Boolean  @default(true)
  sortOrder    Int      @default(0)
  createdAt    DateTime @default(now())
  servers      Server[]
}

/// Mod-manager CATALOG: an installable mod/plugin for a game family. One row per
/// mod per family; customers browse these and one-click install onto their server.
/// Seeded from the per-game mod deep-dive research (name/category/source/id).
model GameMod {
  id               String      @id @default(cuid())
  gameFamily       String // minecraft, rust, valheim, cs2, ark-ase, ark-asa, palworld, terraria, project-zomboid, ...
  name             String
  slug             String // stable per-family kebab identifier
  category         String // Admin, Protection, Economy, Performance, Content, QoL, ...
  // Where it comes from + how the installer fetches it. One of: modrinth, curseforge,
  // hangar, spigotmc, steam_workshop, thunderstore, umod, codefling, nexus, ficsit,
  // rocketmod, factorio_portal, mcpedl, github, manual.
  source           String
  sourceId         String? // workshop id / curseforge project id / modrinth slug / etc.
  url              String?
  modStringId      String? // e.g. Project Zomboid's Mods= string id (distinct from the numeric Workshop id)
  appliesToVariant String? // restrict to a loader/variant (e.g. "paper", "oxide", "carbon"); null = any
  description      String?
  iconUrl          String?
  popularity       Int         @default(0) // higher = more popular (sort key)
  paid             Boolean     @default(false)
  featured         Boolean     @default(false)
  active           Boolean     @default(true)
  createdAt        DateTime    @default(now())
  updatedAt        DateTime    @updatedAt
  installs         ServerMod[]

  // ── Verified upstream facts (scripts/verify-gamemods.ts) ─────────────────
  // Everything below is READ FROM THE SOURCE API, never hand-written: the
  // storefront's previous star ratings and install counts were computed from a
  // hash of the slug, and the fix is not better guesses but real numbers.
  /// Game versions the source says this supports. Empty = the source has no
  /// version list (uMod, Steam Workshop), which is not the same as "none".
  gameVersions    String[]  @default([])
