import { PrismaClient } from "@prisma/client";
const prisma = new PrismaClient();

function line(s=""){ console.log(s); }

const [plans, hostingPlans, gamePlans, emailPlans, coupons, promoActive, referralPartners, nxcloud] = await Promise.all([
  prisma.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
  prisma.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
  prisma.gamePlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
  prisma.emailPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
  prisma.coupon.findMany({ where: { active: true } }),
  prisma.promoRedemption.count().catch(()=>null),
  prisma.referralPartner.findMany(),
  prisma.nxCloudPlan?.findMany?.() ?? [],
]);

line("=== VPS Plans (active) ===");
